using UnityEngine;

namespace SaintVessel
{
    /// <summary>
    /// Keeps the exact MToon shader variants Saint.vrm needs inside the player build.
    /// VRM files are loaded at runtime, so Unity would otherwise strip unused shader_feature variants (pink avatar).
    /// Generated by the editor BuildScript into Assets/Resources/ShaderVariantAnchor.asset.
    /// </summary>
    public sealed class ShaderVariantAnchor : ScriptableObject
    {
        public Material[] materials;
    }
}
